    case Key of
        10 -> 'd_field_trevrpc.interop.v1.EchoResponse_message'(Rest, 0, 0, 0, F@_1, F@_2, TrUserData);
        16 -> 'd_field_trevrpc.interop.v1.EchoResponse_index'(Rest, 0, 0, 0, F@_1, F@_2, TrUserData);
        _ ->
            case Key band 7 of
                0 -> 'skip_varint_trevrpc.interop.v1.EchoResponse'(Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData);
                1 -> 'skip_64_trevrpc.interop.v1.EchoResponse'(Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData);
                2 -> 'skip_length_delimited_trevrpc.interop.v1.EchoResponse'(Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData);
                3 -> 'skip_group_trevrpc.interop.v1.EchoResponse'(Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData);
                5 -> 'skip_32_trevrpc.interop.v1.EchoResponse'(Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData)
            end
    end;
'dg_read_field_def_trevrpc.interop.v1.EchoResponse'(<<>>, 0, 0, _, F@_1, F@_2, _) -> #{message => F@_1, index => F@_2}.

'd_field_trevrpc.interop.v1.EchoResponse_message'(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, TrUserData) when N < 57 -> 'd_field_trevrpc.interop.v1.EchoResponse_message'(Rest, N + 7, X bsl N + Acc, F, F@_1, F@_2, TrUserData);
