    {NewFValue, RestF} = begin Len = X bsl N + Acc, <<Bytes:Len/binary, Rest2/binary>> = Rest, Bytes2 = binary:copy(Bytes), {id(Bytes2, TrUserData), Rest2} end,
    'dfp_read_field_def_trevrpc.interop.v1.EchoResponse'(RestF, 0, 0, F, NewFValue, F@_2, TrUserData).

'd_field_trevrpc.interop.v1.EchoResponse_index'(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, TrUserData) when N < 57 -> 'd_field_trevrpc.interop.v1.EchoResponse_index'(Rest, N + 7, X bsl N + Acc, F, F@_1, F@_2, TrUserData);
