    {NewFValue, RestF} = {id((X bsl N + Acc) band 4294967295, TrUserData), Rest},
    'dfp_read_field_def_trevrpc.interop.v1.EchoResponse'(RestF, 0, 0, F, F@_1, NewFValue, TrUserData).

'skip_varint_trevrpc.interop.v1.EchoResponse'(<<1:1, _:7, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, TrUserData) -> 'skip_varint_trevrpc.interop.v1.EchoResponse'(Rest, Z1, Z2, F, F@_1, F@_2, TrUserData);
'skip_varint_trevrpc.interop.v1.EchoResponse'(<<0:1, _:7, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, TrUserData) -> 'dfp_read_field_def_trevrpc.interop.v1.EchoResponse'(Rest, Z1, Z2, F, F@_1, F@_2, TrUserData).

