'skip_32_trevrpc.interop.v1.EchoResponse'(<<_:32, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, TrUserData) -> 'dfp_read_field_def_trevrpc.interop.v1.EchoResponse'(Rest, Z1, Z2, F, F@_1, F@_2, TrUserData).

'skip_64_trevrpc.interop.v1.EchoResponse'(<<_:64, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, TrUserData) -> 'dfp_read_field_def_trevrpc.interop.v1.EchoResponse'(Rest, Z1, Z2, F, F@_1, F@_2, TrUserData).

'decode_msg_trevrpc.interop.v1.PlainMessage'(Bin, TrUserData) -> 'dfp_read_field_def_trevrpc.interop.v1.PlainMessage'(Bin, 0, 0, 0, id(<<>>, TrUserData), TrUserData).

'dfp_read_field_def_trevrpc.interop.v1.PlainMessage'(<<10, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> 'd_field_trevrpc.interop.v1.PlainMessage_text'(Rest, Z1, Z2, F, F@_1, TrUserData);
'dfp_read_field_def_trevrpc.interop.v1.PlainMessage'(<<>>, 0, 0, _, F@_1, _) -> #{text => F@_1};
'dfp_read_field_def_trevrpc.interop.v1.PlainMessage'(Other, Z1, Z2, F, F@_1, TrUserData) -> 'dg_read_field_def_trevrpc.interop.v1.PlainMessage'(Other, Z1, Z2, F, F@_1, TrUserData).

'dg_read_field_def_trevrpc.interop.v1.PlainMessage'(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, TrUserData) when N < 32 - 7 -> 'dg_read_field_def_trevrpc.interop.v1.PlainMessage'(Rest, N + 7, X bsl N + Acc, F, F@_1, TrUserData);
