                5 -> 'skip_32_trevrpc.interop.v1.PlainMessage'(Rest, 0, 0, Key bsr 3, F@_1, TrUserData)
            end
    end;
'dg_read_field_def_trevrpc.interop.v1.PlainMessage'(<<>>, 0, 0, _, F@_1, _) -> #{text => F@_1}.

