'skip_64_trevrpc.interop.v1.PlainMessage'(<<_:64, Rest/binary>>, Z1, Z2, F, F@_1, TrUserData) -> 'dfp_read_field_def_trevrpc.interop.v1.PlainMessage'(Rest, Z1, Z2, F, F@_1, TrUserData).

read_group(Bin, FieldNum) ->
    {NumBytes, EndTagLen} = read_gr_b(Bin, 0, 0, 0, 0, FieldNum),
    <<Group:NumBytes/binary, _:EndTagLen/binary, Rest/binary>> = Bin,
    {Group, Rest}.

%% Like skipping over fields, but record the total length,
%% Each field is <(FieldNum bsl 3) bor FieldType> ++ <FieldValue>
%% Record the length because varints may be non-optimally encoded.
%%
%% Groups can be nested, but assume the same FieldNum cannot be nested
%% because group field numbers are shared with the rest of the fields
%% numbers. Thus we can search just for an group-end with the same
%% field number.
%%
%% (The only time the same group field number could occur would
%% be in a nested sub message, but then it would be inside a
%% length-delimited entry, which we skip-read by length.)
read_gr_b(<<1:1, X:7, Tl/binary>>, N, Acc, NumBytes, TagLen, FieldNum)
  when N < (32-7) ->
    read_gr_b(Tl, N+7, X bsl N + Acc, NumBytes, TagLen+1, FieldNum);
read_gr_b(<<0:1, X:7, Tl/binary>>, N, Acc, NumBytes, TagLen,
          FieldNum) ->
    Key = X bsl N + Acc,
    TagLen1 = TagLen + 1,
    case {Key bsr 3, Key band 7} of
        {FieldNum, 4} -> % 4 = group_end
            {NumBytes, TagLen1};
        {_, 0} -> % 0 = varint
            read_gr_vi(Tl, 0, NumBytes + TagLen1, FieldNum);
        {_, 1} -> % 1 = bits64
            <<_:64, Tl2/binary>> = Tl,
            read_gr_b(Tl2, 0, 0, NumBytes + TagLen1 + 8, 0, FieldNum);
        {_, 2} -> % 2 = length_delimited
            read_gr_ld(Tl, 0, 0, NumBytes + TagLen1, FieldNum);
        {_, 3} -> % 3 = group_start
            read_gr_b(Tl, 0, 0, NumBytes + TagLen1, 0, FieldNum);
        {_, 4} -> % 4 = group_end
            read_gr_b(Tl, 0, 0, NumBytes + TagLen1, 0, FieldNum);
        {_, 5} -> % 5 = bits32
            <<_:32, Tl2/binary>> = Tl,
            read_gr_b(Tl2, 0, 0, NumBytes + TagLen1 + 4, 0, FieldNum)
    end.

read_gr_vi(<<1:1, _:7, Tl/binary>>, N, NumBytes, FieldNum)
  when N < (64-7) ->
    read_gr_vi(Tl, N+7, NumBytes+1, FieldNum);
read_gr_vi(<<0:1, _:7, Tl/binary>>, _, NumBytes, FieldNum) ->
    read_gr_b(Tl, 0, 0, NumBytes+1, 0, FieldNum).

read_gr_ld(<<1:1, X:7, Tl/binary>>, N, Acc, NumBytes, FieldNum)
  when N < (64-7) ->
    read_gr_ld(Tl, N+7, X bsl N + Acc, NumBytes+1, FieldNum);
read_gr_ld(<<0:1, X:7, Tl/binary>>, N, Acc, NumBytes, FieldNum) ->
    Len = X bsl N + Acc,
    NumBytes1 = NumBytes + 1,
    <<_:Len/binary, Tl2/binary>> = Tl,
    read_gr_b(Tl2, 0, 0, NumBytes1 + Len, 0, FieldNum).

merge_msgs(Prev, New, MsgName) when is_atom(MsgName) -> merge_msgs(Prev, New, MsgName, []).

merge_msgs(Prev, New, MsgName, Opts) ->
    TrUserData = proplists:get_value(user_data, Opts),
    case MsgName of
        'trevrpc.interop.v1.EchoRequest' -> 'merge_msg_trevrpc.interop.v1.EchoRequest'(Prev, New, TrUserData);
        'trevrpc.interop.v1.EchoResponse' -> 'merge_msg_trevrpc.interop.v1.EchoResponse'(Prev, New, TrUserData);
        'trevrpc.interop.v1.PlainMessage' -> 'merge_msg_trevrpc.interop.v1.PlainMessage'(Prev, New, TrUserData)
    end.

-compile({nowarn_unused_function,'merge_msg_trevrpc.interop.v1.EchoRequest'/3}).
'merge_msg_trevrpc.interop.v1.EchoRequest'(PMsg, NMsg, _) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
             {_, #{message := NFmessage}} -> S1#{message => NFmessage};
             {#{message := PFmessage}, _} -> S1#{message => PFmessage};
             _ -> S1
         end,
    S3 = case {PMsg, NMsg} of
             {_, #{count := NFcount}} -> S2#{count => NFcount};
             {#{count := PFcount}, _} -> S2#{count => PFcount};
             _ -> S2
         end,
    S4 = case {PMsg, NMsg} of
             {_, #{fail_code := NFfail_code}} -> S3#{fail_code => NFfail_code};
             {#{fail_code := PFfail_code}, _} -> S3#{fail_code => PFfail_code};
             _ -> S3
         end,
    case {PMsg, NMsg} of
        {_, #{fail_message := NFfail_message}} -> S4#{fail_message => NFfail_message};
        {#{fail_message := PFfail_message}, _} -> S4#{fail_message => PFfail_message};
        _ -> S4
    end.

-compile({nowarn_unused_function,'merge_msg_trevrpc.interop.v1.EchoResponse'/3}).
'merge_msg_trevrpc.interop.v1.EchoResponse'(PMsg, NMsg, _) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
             {_, #{message := NFmessage}} -> S1#{message => NFmessage};
             {#{message := PFmessage}, _} -> S1#{message => PFmessage};
             _ -> S1
         end,
    case {PMsg, NMsg} of
        {_, #{index := NFindex}} -> S2#{index => NFindex};
        {#{index := PFindex}, _} -> S2#{index => PFindex};
        _ -> S2
    end.

-compile({nowarn_unused_function,'merge_msg_trevrpc.interop.v1.PlainMessage'/3}).
'merge_msg_trevrpc.interop.v1.PlainMessage'(PMsg, NMsg, _) ->
    S1 = #{},
    case {PMsg, NMsg} of
        {_, #{text := NFtext}} -> S1#{text => NFtext};
        {#{text := PFtext}, _} -> S1#{text => PFtext};
        _ -> S1
    end.


verify_msg(Msg, MsgName) when is_atom(MsgName) -> verify_msg(Msg, MsgName, []).

verify_msg(Msg, MsgName, Opts) ->
    TrUserData = proplists:get_value(user_data, Opts),
    case MsgName of
        'trevrpc.interop.v1.EchoRequest' -> 'v_msg_trevrpc.interop.v1.EchoRequest'(Msg, [MsgName], TrUserData);
        'trevrpc.interop.v1.EchoResponse' -> 'v_msg_trevrpc.interop.v1.EchoResponse'(Msg, [MsgName], TrUserData);
        'trevrpc.interop.v1.PlainMessage' -> 'v_msg_trevrpc.interop.v1.PlainMessage'(Msg, [MsgName], TrUserData);
        _ -> mk_type_error(not_a_known_message, Msg, [])
    end.


-compile({nowarn_unused_function,'v_msg_trevrpc.interop.v1.EchoRequest'/3}).
-dialyzer({nowarn_function,'v_msg_trevrpc.interop.v1.EchoRequest'/3}).
'v_msg_trevrpc.interop.v1.EchoRequest'(#{} = M, Path, TrUserData) ->
    case M of
        #{message := F1} -> v_type_string(F1, [message | Path], TrUserData);
        _ -> ok
    end,
    case M of
        #{count := F2} -> v_type_uint32(F2, [count | Path], TrUserData);
        _ -> ok
    end,
    case M of
        #{fail_code := F3} -> v_type_uint32(F3, [fail_code | Path], TrUserData);
        _ -> ok
    end,
    case M of
        #{fail_message := F4} -> v_type_string(F4, [fail_message | Path], TrUserData);
        _ -> ok
    end,
    lists:foreach(fun (message) -> ok;
                      (count) -> ok;
                      (fail_code) -> ok;
                      (fail_message) -> ok;
                      (OtherKey) -> mk_type_error({extraneous_key, OtherKey}, M, Path)
                  end,
                  maps:keys(M)),
    ok;
'v_msg_trevrpc.interop.v1.EchoRequest'(M, Path, _TrUserData) when is_map(M) -> mk_type_error({missing_fields, [] -- maps:keys(M), 'trevrpc.interop.v1.EchoRequest'}, M, Path);
'v_msg_trevrpc.interop.v1.EchoRequest'(X, Path, _TrUserData) -> mk_type_error({expected_msg, 'trevrpc.interop.v1.EchoRequest'}, X, Path).

-compile({nowarn_unused_function,'v_msg_trevrpc.interop.v1.EchoResponse'/3}).
-dialyzer({nowarn_function,'v_msg_trevrpc.interop.v1.EchoResponse'/3}).
'v_msg_trevrpc.interop.v1.EchoResponse'(#{} = M, Path, TrUserData) ->
    case M of
        #{message := F1} -> v_type_string(F1, [message | Path], TrUserData);
        _ -> ok
    end,
    case M of
        #{index := F2} -> v_type_uint32(F2, [index | Path], TrUserData);
        _ -> ok
    end,
    lists:foreach(fun (message) -> ok;
                      (index) -> ok;
                      (OtherKey) -> mk_type_error({extraneous_key, OtherKey}, M, Path)
                  end,
                  maps:keys(M)),
    ok;
'v_msg_trevrpc.interop.v1.EchoResponse'(M, Path, _TrUserData) when is_map(M) -> mk_type_error({missing_fields, [] -- maps:keys(M), 'trevrpc.interop.v1.EchoResponse'}, M, Path);
'v_msg_trevrpc.interop.v1.EchoResponse'(X, Path, _TrUserData) -> mk_type_error({expected_msg, 'trevrpc.interop.v1.EchoResponse'}, X, Path).

-compile({nowarn_unused_function,'v_msg_trevrpc.interop.v1.PlainMessage'/3}).
-dialyzer({nowarn_function,'v_msg_trevrpc.interop.v1.PlainMessage'/3}).
'v_msg_trevrpc.interop.v1.PlainMessage'(#{} = M, Path, TrUserData) ->
    case M of
        #{text := F1} -> v_type_string(F1, [text | Path], TrUserData);
        _ -> ok
    end,
    lists:foreach(fun (text) -> ok;
                      (OtherKey) -> mk_type_error({extraneous_key, OtherKey}, M, Path)
                  end,
                  maps:keys(M)),
    ok;
'v_msg_trevrpc.interop.v1.PlainMessage'(M, Path, _TrUserData) when is_map(M) -> mk_type_error({missing_fields, [] -- maps:keys(M), 'trevrpc.interop.v1.PlainMessage'}, M, Path);
'v_msg_trevrpc.interop.v1.PlainMessage'(X, Path, _TrUserData) -> mk_type_error({expected_msg, 'trevrpc.interop.v1.PlainMessage'}, X, Path).

-compile({nowarn_unused_function,v_type_uint32/3}).
-dialyzer({nowarn_function,v_type_uint32/3}).
v_type_uint32(N, _Path, _TrUserData) when is_integer(N), 0 =< N, N =< 4294967295 -> ok;
v_type_uint32(N, Path, _TrUserData) when is_integer(N) -> mk_type_error({value_out_of_range, uint32, unsigned, 32}, N, Path);
v_type_uint32(X, Path, _TrUserData) -> mk_type_error({bad_integer, uint32, unsigned, 32}, X, Path).

-compile({nowarn_unused_function,v_type_string/3}).
-dialyzer({nowarn_function,v_type_string/3}).
v_type_string(S, Path, _TrUserData) when is_list(S); is_binary(S) ->
    try unicode:characters_to_binary(S) of
        B when is_binary(B) -> ok;
        {error, _, _} -> mk_type_error(bad_unicode_string, S, Path)
    catch
        error:badarg -> mk_type_error(bad_unicode_string, S, Path)
    end;
v_type_string(X, Path, _TrUserData) -> mk_type_error(bad_unicode_string, X, Path).

-compile({nowarn_unused_function,mk_type_error/3}).
-spec mk_type_error(_, _, list()) -> no_return().
mk_type_error(Error, ValueSeen, Path) ->
    Path2 = prettify_path(Path),
    erlang:error({gpb_type_error, {Error, [{value, ValueSeen}, {path, Path2}]}}).


-compile({nowarn_unused_function,prettify_path/1}).
-dialyzer({nowarn_function,prettify_path/1}).
prettify_path([]) -> top_level;
prettify_path(PathR) -> lists:append(lists:join(".", lists:map(fun atom_to_list/1, lists:reverse(PathR)))).


-compile({nowarn_unused_function,id/2}).
-compile({inline,id/2}).
id(X, _TrUserData) -> X.

-compile({nowarn_unused_function,v_ok/3}).
-compile({inline,v_ok/3}).
v_ok(_Value, _Path, _TrUserData) -> ok.

-compile({nowarn_unused_function,m_overwrite/3}).
-compile({inline,m_overwrite/3}).
m_overwrite(_Prev, New, _TrUserData) -> New.

-compile({nowarn_unused_function,cons/3}).
-compile({inline,cons/3}).
cons(Elem, Acc, _TrUserData) -> [Elem | Acc].

-compile({nowarn_unused_function,lists_reverse/2}).
-compile({inline,lists_reverse/2}).
'lists_reverse'(L, _TrUserData) -> lists:reverse(L).
-compile({nowarn_unused_function,'erlang_++'/3}).
-compile({inline,'erlang_++'/3}).
'erlang_++'(A, B, _TrUserData) -> A ++ B.


